INSERT INTO analyses (id, submission_id, enrichment_id, company_id, swot, pestel, porter, okrs, synthesis, tam_sam_som, benchmarking, blue_ocean, growth_hacking, scenarios, bsc, decision_matrix, status, error_message, processing_time_ms, is_visible_to_user, is_blurred, is_public, access_code, access_code_created_at, pdf_url, pdf_generated_at, approved_at, approved_by, sent_at, sent_to, created_at, updated_at, completed_at, deleted_at)
VALUES ('0935778d-a8d8-4b2d-bf6b-df11d6c6f1e1', NULL, NULL, NULL, '{"summary": "Marca eco-luxury forte e digitalmente madura, com espaço para escalar SPAs, amenities e Santopé, mas sob pressão de juros altos e gigantes globais.", "threats": [{"source": "análise de mercado", "content": "Rivalidade intensa com L''Occitane, Natura, Boticário no luxo e bem-estar", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Hotéis e SPAs com alto poder de barganha pressionando preço e condições", "confidence": "Média"}, {"source": "análise de mercado", "content": "Câmbio USD/BRL R$ 5.36 encarece insumos importados e viagens internacionais", "confidence": "Média"}, {"source": "análise de mercado", "content": "Regulação ANVISA e normas verdes elevam custos e risco em novos SKUs e SPAs", "confidence": "Média"}], "strengths": [{"source": "fato", "content": "Origem nos hotéis Emiliano, com prova social forte em hospitalidade de luxo", "confidence": "Alta"}, {"source": "fato", "content": "Posicionamento claro de eco-luxury, alinhado à alta renda e sustentabilidade", "confidence": "Alta"}, {"source": "fato", "content": "Modelo híbrido: SPAs franqueados, amenities B2B e D2C com ecommerce próprio", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Boa maturidade digital (8/10) para acelerar aquisição D2C e relacionamento", "confidence": "Média"}], "weaknesses": [{"source": "análise de mercado", "content": "Escala e orçamento de marketing menores que L''Occitane, Natura e Boticário", "confidence": "Média"}, {"source": "fato", "content": "Dependência da marca Emiliano para reconhecimento e prova de qualidade", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Capital próprio limitado em cenário de SELIC 14.90%, freando expansão rápida", "confidence": "Média"}, {"source": "análise de mercado", "content": "Complexidade de operar hotelaria, ecommerce, franquias e futuro canal farma", "confidence": "Média"}], "opportunities": [{"source": "análise de mercado", "content": "Escalar franquias de SPA em hotéis 5* além do Emiliano, rivalizando L''Occitane", "confidence": "Média"}, {"source": "análise de mercado", "content": "Expandir venda de amenities eco-luxury para redes de hotéis de luxo globais", "confidence": "Média"}, {"source": "fato", "content": "Lançar linha Santopé completa e ganhar nicho premium de cuidados para pés", "confidence": "Alta"}, {"source": "estimativa", "content": "Entrar em farmácias selecionadas com Santopé, reforçando awareness D2C", "confidence": "Média"}]}'::jsonb, '{"legal": ["Regulamentações ANVISA podem endurecer testes e alegações naturais, exigindo investimento em P&D regulatório.", "Evolução de normas ambientais traz risco de multas se comunicação eco-luxury não tiver lastro documental.", "Expansão via franquias de SPA exige contratos robustos frente ao CDC, evitando conflitos sobre experiência."], "social": ["Desemprego em 5,60% mantém consumo seletivo; branding forte é crítico para a marca eco-luxury.", "Inflação baixa (0,09% a.a.) preserva poder de compra da alta renda, apoiando tickets elevados no D2C.", "Busca por bem-estar e autocuidado abre janela para linha Santopé liderar categoria premium de pés."], "summary": "Juros altos, serviços em alta e câmbio pró-turismo criam cenário misto. Escalar SPAs e novas linhas com rigor regulatório e autenticidade eco-luxury será chave para capturar o ciclo de bem-estar.", "economic": ["Juros de 14,90% a.a. encarecem capital; franquias de SPA ganham apelo como modelo asset-light.", "PIB +2,20% e serviços +0,60% sugerem retomada gradual da demanda B2B por amenities e SPAs premium.", "Câmbio a R$ 5,36/USD encarece insumos importados, mas reforça atratividade do Brasil para turistas."], "political": ["Política monetária restritiva (juros 14,90% a.a.) limita crédito para expansão de SPAs parceiras.", "Serviços em alta (+0,60%) tende a ganhar atenção política, abrindo espaço a pautas pró-turismo wellness.", "Agenda pública de sustentabilidade pode priorizar hotelaria verde, favorecendo proposta eco-luxury da marca."], "environmental": ["Normas de sustentabilidade ambiental tendem a exigir métricas de impacto; oportunidade de liderar transparência.", "Pressão por cadeias limpas favorece fornecedores locais, reduzindo exposição ao câmbio de R$ 5,36/USD.", "Turismo consciente valoriza amenities recarregáveis/refil; chance de testar modelos circulares com hotéis."], "technological": ["Aceleração do ecommerce/D2C permite testar novos SKUs Santopé com baixo risco e feedback rico do cliente.", "Logística verde e compensação de carbono viram requisito em redes hoteleiras; atual vantagem pode commoditizar.", "Maturidade digital 8/10 habilita personalização online superior à de concorrentes tradicionais de cosméticos."]}'::jsonb, '{"summary": "Mercado atrativo porém exigente: rivalidade e poder de compradores são altos, mas crescimento em serviços (0.60%), narrativa eco-luxury e parcerias em hospitalidade criam espaço para captar valor via diferenciação e ações RACE em B2B e D2C.", "buyer_power": "Alto poder dos compradores: hotéis de luxo e redes farma concentram demanda e pressionam descontos; com comércio em -0.30% e desemprego em 5.60%, consumidor final fica seletivo, exigindo valor percebido e experiência superior.", "supplier_power": "Alto poder dos fornecedores: insumos e embalagens premium, muitos atrelados ao dólar a R$ 5.36/USD, somados ao juros de 14.90% a.a., comprimem margens e limitam capacidade da Santapele de renegociar preços e prazos.", "disruption_ai_data": "Disrupção por IA/dados média: D2C de beleza acelera uso de IA para personalização, mídia paga e CRM; sem investir em analytics proprietário, a Santapele perde eficiência de aquisição e retenção frente a players digitais mais capitalizados.", "threat_substitutes": "Ameaça alta de substitutos: amenities genéricos mais baratos, marcas globais em SPAs e dermocosméticos farma oferecem alternativas; juros de 14.90% e dólar a R$ 5.36/USD incentivam hotéis a migrar para opções de menor custo ou white label.", "competitive_rivalry": "Rivalidade alta: Natura, Boticário, Granado e L’Occitane disputam nicho premium; retração do comércio em -0.30% força guerra por contratos B2B e share D2C, exigindo diferenciação forte em eco-luxo e SPA autoral.", "threat_new_entrants": "Ameaça média: crescimento de serviços em 0.60% atrai novos SPAs e marcas indie D2C, mas exigências ANVISA, certificações verdes e capital caro a 14.90% a.a. elevam barreiras e protegem o posicionamento eco-luxury da Santapele.", "buyer_power_intensity": "Alta", "overall_attractiveness": "Média", "strategic_implications": ["Fortalecer contratos âncora com redes de hotéis e SPAs, com propostas exclusivas e SLAs rígidos.", "Criar plataforma D2C orientada por dados, com personalização de jornada e programa de fidelidade.", "Desenvolver sourcing sustentável multi-fornecedor para reduzir risco cambial e de concentração.", "Acelerar uso de IA em mídia, precificação e previsão de demanda para ganhar eficiência em escala."], "supplier_power_intensity": "Alta", "disruption_ai_data_intensity": "Média", "threat_substitutes_intensity": "Alta", "competitive_rivalry_intensity": "Alta", "power_partnerships_ecosystems": "Parcerias têm poder alto: serviços em alta (0.60%) favorecem expansão com redes hoteleiras, SPAs, farmácias e marketplaces; alianças em sustentabilidade e logística verde reforçam narrativa eco-luxury e ampliam alcance B2B e D2C.", "threat_new_entrants_intensity": "Média", "power_partnerships_ecosystems_intensity": "Alta"}'::jsonb, '{"summary": "Plano de 90 dias para estruturar D2C eco-luxury, pilotar Santopé e preparar expansão B2B/SPAs.", "plan_90_days": [{"focus": "Fundação", "month": "Mês 1", "objective": "Estruturar base D2C eco-luxury com dados, LGPD e visão integrada de canais", "investment": "R$ 10-20 mil", "key_results": ["Selecionar e contratar ferramenta de CRM integrada ao ecommerce. Resp: Marketing", "Revisar LGPD, termos e política de privacidade do site. Resp: Jurídico", "Mapear jornada D2C e definir 3 personas prioritárias. Resp: Conselho/Marketing"], "aligned_recommendation": "Fortalecer D2C e comunidade de marca eco-luxury"}, {"focus": "Crescimento", "month": "Mês 2", "objective": "Desenvolver e lançar piloto da linha Santopé em D2C e canal farma selecionado", "investment": "R$ 20-40 mil", "key_results": ["Concluir desenvolvimento de 3-4 SKUs Santopé com ANVISA ok. Resp: P&D", "Lançar piloto Santopé no ecommerce com 2 bundles testados. Resp: Marketing", "Fechar 1 contrato-piloto com farmácia premium em SP. Resp: Comercial"], "aligned_recommendation": "Desenvolver e pilotar a linha Santopé como plataforma de cuidado premium para os pés"}, {"focus": "Consolidação", "month": "Mês 3", "objective": "Preparar modelo asset-light para expansão B2B em hotéis de luxo e SPAs", "investment": "R$ 30-50 mil", "key_results": ["Desenhar playbook preliminar de franquia/SPA Emiliano. Resp: Operações", "Identificar e priorizar 5 hotéis-alvo para amenities e SPA. Resp: Comercial", "Obter parecer jurídico inicial sobre franquias e contratos. Resp: Jurídico"], "aligned_recommendation": "Expansão seletiva B2B em hotelaria de luxo e SPAs franqueados (modelo asset-light)"}], "success_metrics": ["CRM D2C implantado e operante com base unificada de clientes", "Linha Santopé com 3-4 SKUs pronta e piloto ativo em ecommerce/farma", "Playbook inicial de SPA/franquia e pipeline de hotéis-alvo estruturados"], "execution_phases": {"scale": {"focus": "Expansão controlada", "duration": "Meses 7-12", "objectives": ["Escalar D2C eco-luxury com foco em recorrência e comunidade", "Ampliar rede de hotéis e SPAs franqueados em modelo asset-light"], "key_results": ["Alcançar 3 SPAs franqueados operando com playbook padronizado", "Fechar 8-10 novos contratos de amenities em hotéis de luxo"], "prerequisites": ["Validação bem-sucedida de Santopé, D2C e pilotos B2B", "Métricas mínimas de giro, margem e satisfação atingidas"], "investment_range": "R$ 150-200 mil"}, "foundation": {"focus": "Estruturação", "duration": "Meses 1-3", "objectives": ["Criar base jurídica, digital e de dados para D2C, Santopé e B2B", "Estruturar governança mínima para franquias e expansão hotelaria"], "key_results": ["CRM unificado ativo para D2C e relacionamento B2B", "Políticas LGPD, ANVISA e minuta-base de franquia definidas"], "investment_range": "R$ 60-110 mil", "capacity_requirements": {"team": "4-6 pessoas", "dependencies": ["Advogado externo especializado em digital, ANVISA e franchising", "Parceiros de logística e meios de pagamento para ecommerce"], "skills_needed": ["Marketing digital e CRM D2C", "Jurídico regulatório (LGPD, ANVISA, franquias)", "Comercial B2B hotelaria de luxo", "Gestão de produto cosmético e P&D"]}}, "validation": {"focus": "Pilotos", "duration": "Meses 4-6", "objectives": ["Validar aceitação da linha Santopé em ecommerce e 1-2 farmácias premium", "Testar pilotos de amenities e/ou SPA em 1-2 hotéis fora da base Emiliano"], "key_results": ["2 pilotos Santopé ativos (ecommerce e pelo menos 1 farmácia)", "1 contrato-piloto ativo de SPA ou amenities em novo hotel"], "prerequisites": ["Fase 1 concluída", "Aprovações e pareceres jurídicos críticos obtidos"], "investment_range": "R$ 80-120 mil"}}, "total_investment": "R$ 60-110 mil", "capacity_assessment": {"blockers": ["Capital próprio limitado em cenário de SELIC 14.90%, exigindo expansão asset-light", "Ausência de equipe dedicada a franquias e canal farma aumenta risco de sobrecarga"], "team_readiness": "Média", "budget_adequacy": "Limitado", "stakeholder_alignment": "Parcial"}}'::jsonb, '{"roadmap": ["Curto Prazo (3-6 meses): Estruturar clube de assinatura D2C, lançar linha completa Santopé (4-5 SKUs), fechar 2 pilotos B2B hotelaria", "Médio Prazo (6-12 meses): Escalar Santopé para 3 redes Farma, converter pilotos B2B em contratos recorrentes, validar modelo de franquia SPA com 1-2 unidades", "Longo Prazo (12+ meses): Expandir franquias SPA 